"""Generate the native setup and uninstall design tokens from the shared JSON."""

from __future__ import annotations

import argparse
import json
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SOURCE = ROOT / "packaging/windows/setup/tokens.json"
OUTPUTS = {
    "cpp": ROOT / "packaging/windows/bootstrapper/setup_tokens.h",
    "rust": ROOT / "crates/usque-uninstall/src/tokens_generated.rs",
}
NOTICE = (
    "Generated by tool/generate_windows_setup_tokens.py; edit packaging/windows/setup/tokens.json."
)
THEMES = ("light", "dark")


def unique_object(pairs: list[tuple[str, object]]) -> dict[str, object]:
    result: dict[str, object] = {}
    for key, value in pairs:
        if key in result:
            raise ValueError(f"Duplicate token: {key}")
        result[key] = value
    return result


def parse_hex(value: object) -> tuple[int, int, int]:
    if not isinstance(value, str) or not re.fullmatch(r"#[0-9A-F]{6}", value):
        raise ValueError(f"Colors must be #RRGGBB in upper case: {value!r}")
    return int(value[1:3], 16), int(value[3:5], 16), int(value[5:7], 16)


def mix(tone: tuple[int, int, int], base: tuple[int, int, int], amount: float):
    """Tone at `amount` opacity over an opaque base, rounded half up."""
    return tuple(int(t * amount + b * (1 - amount) + 0.5) for t, b in zip(tone, base, strict=True))


def scale(color: tuple[int, int, int], factor: float):
    """Darkens like the former native pressed accent: (channel * 9 + 5) / 10."""
    if factor != 0.9:
        raise ValueError("Only the established 0.9 pressed scale is supported")
    return tuple((channel * 9 + 5) // 10 for channel in color)


def load(path: Path = SOURCE) -> dict[str, object]:
    tokens = json.loads(path.read_text(encoding="utf-8"), object_pairs_hook=unique_object)
    if tokens.get("schema") != 1:
        raise ValueError("Unsupported token schema")
    palettes: dict[str, dict[str, tuple[int, int, int]]] = {theme: {} for theme in THEMES}
    for name, entry in tokens["colors"].items():
        if not re.fullmatch(r"[a-z][a-z0-9_]*", name):
            raise ValueError(f"Invalid token name: {name}")
        for theme in THEMES:
            palettes[theme][name] = parse_hex(entry[theme])
    ratios: dict[str, dict[str, float]] = {theme: {} for theme in THEMES}
    for name, entry in tokens.get("ratios", {}).items():
        for theme in THEMES:
            value = entry[theme]
            if isinstance(value, bool) or not isinstance(value, (int, float)) or not 0 < value < 1:
                raise ValueError(f"Ratios must be between 0 and 1: {name}")
            ratios[theme][name] = float(value)
    for name, rule in tokens["derived"].items():
        if name in palettes["light"]:
            raise ValueError(f"Derived token shadows a color: {name}")
        ((kind, arguments),) = rule.items()
        for theme in THEMES:
            palette = palettes[theme]
            if kind == "mix":
                tone, base, amount = arguments
                # A named ratio such as Flutter's tint differs per theme.
                amount = ratios[theme][amount] if isinstance(amount, str) else float(amount)
                palette[name] = mix(palette[tone], palette[base], amount)
            elif kind == "scale":
                color, factor = arguments
                palette[name] = scale(palette[color], float(factor))
            else:
                raise ValueError(f"Unknown derivation: {kind}")
    metrics: dict[str, int | float] = {}
    for name, entry in tokens["metrics"].items():
        value = entry["value"]
        if isinstance(value, bool) or not isinstance(value, (int, float)) or value <= 0:
            raise ValueError(f"Metrics must be positive numbers: {name}")
        metrics[name] = value
    return {"source": tokens, "palettes": palettes, "metrics": metrics}


def colorref(color: tuple[int, int, int]) -> str:
    red, green, blue = color
    return f"0x00{blue:02x}{green:02x}{red:02x}"


def render(model: dict[str, object]) -> dict[str, str]:
    palettes = model["palettes"]
    metrics = model["metrics"]
    names = list(palettes["light"])
    cpp = [
        f"// {NOTICE}",
        "#pragma once",
        "",
        "#include <windows.h>",
        "",
        "namespace usque::setup {",
        "// Win32 COLORREF values (0x00BBGGRR) matching the Flutter theme.",
        "struct Tokens {",
    ]
    cpp += [f"  COLORREF {name};" for name in names]
    cpp += ["};", ""]
    rust = [
        f"// {NOTICE}",
        "",
        "/// Win32 COLORREF values (0x00BBGGRR) matching the Flutter theme.",
        "#[derive(Clone, Copy, Debug, PartialEq, Eq)]",
        "pub struct Tokens {",
    ]
    rust += [f"    pub {name}: u32," for name in names]
    rust += ["}", ""]
    for theme in THEMES:
        upper = theme.upper()
        cpp.append(f"inline constexpr Tokens k{theme.capitalize()}Tokens{{")
        cpp += [f"  {colorref(palettes[theme][name])},  // {name}" for name in names]
        cpp += ["};", ""]
        rust.append(f"pub const {upper}: Tokens = Tokens {{")
        rust += [f"    {name}: {colorref(palettes[theme][name])}," for name in names]
        rust += ["};", ""]
    cpp += [
        "constexpr const Tokens& ThemeTokens(bool dark) { return dark ? kDarkTokens : kLightTokens; }",
        "",
    ]
    rust += [
        "pub const fn theme(dark: bool) -> &'static Tokens {",
        "    if dark { &DARK } else { &LIGHT }",
        "}",
        "",
    ]
    for name, value in metrics.items():
        camel = "".join(part.capitalize() for part in name.split("_"))
        if isinstance(value, float):
            cpp.append(f"inline constexpr float k{camel} = {value}f;")
            rust.append(f"pub const {name.upper()}: f32 = {value};")
        else:
            cpp.append(f"inline constexpr int k{camel} = {value};")
            rust.append(f"pub const {name.upper()}: i32 = {value};")
    cpp += ["}  // namespace usque::setup", ""]
    return {"cpp": "\n".join(cpp), "rust": "\n".join(rust) + "\n"}


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    stale = []
    for language, contents in render(load()).items():
        path = OUTPUTS[language]
        if args.check:
            if not path.exists() or path.read_text(encoding="utf-8") != contents:
                stale.append(str(path.relative_to(ROOT)))
        else:
            path.write_text(contents, encoding="utf-8", newline="\n")
    if stale:
        parser.exit(1, "Stale setup token projections: " + ", ".join(stale) + "\n")
    print("SETUP_TOKENS_OK")


if __name__ == "__main__":
    main()
